    void turnOff() {
        isOn = false;
        System.out.println("Bulb is OFF");
    }
}

public class Main {
    public static void main(String[] args) {
        LightBulb bulb = new LightBulb();
        bulb.turnOn();
        bulb.turnOff();
    }
}

