class BankAccount {
    double balance = 1000.0;

    void deposit(double amount) {
        balance = balance + amount;
    }

    void withdraw(double amount) {
        balance = balance - amount;
    }

    void printBalance() {
        System.out.println("Balance: $" + balance);
    }
}

public class Main {
    public static void main(String[] args) {
        BankAccount b = new BankAccount();
        b.deposit(250.0);
        b.withdraw(100.0);
        b.printBalance();
    }
}

