practiceProblems.solutionCode:
class Car {
    int fuelLevel = 50;

    void drive(int fuelUsed) {
        fuelLevel = fuelLevel - fuelUsed;
    }

    void refuel(int fuelAdded) {
        fuelLevel = fuelLevel + fuelAdded;
    }
}

public class Main {
    public static void main(String[] args) {
        Car c = new Car();
        c.drive(15);
        c.refuel(20);
        System.out.println("Current Fuel: " + c.fuelLevel + "L");
    }
}

